function icon(name) { return `<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${paths[name] || ''}</svg>`; }
function initialDb() { const cases = cloneSeeds(); return { cases, currentId: cases[0].id }; }
let storageWarning = '';
let storageLocked = false;
function loadDb() {
  try {
    const raw = localStorage.getItem(STORE);
    if (!raw) return initialDb();
    const data = JSON.parse(raw);
    if (!Array.isArray(data.cases) || data.cases.length > 100) throw new Error('Invalid cases');
    const seeds = new Map(cloneSeeds().map(c => [c.id, c]));
    const oldTitles = { 'published-lakshmi-2022':'حالة لاكشمي ديفي', 'published-vikas-2023':'رواية فيكاس كومار' };
    let cases = data.cases.map(validateCase).map(c => {
      // Translate untouched built-in case labels only. User-entered or edited case data is never overwritten.
      if (c.published && c.title === oldTitles[c.id] && seeds.has(c.id)) {
        const original = seeds.get(c.id);
        return { ...c, title:original.title, scope:original.scope, description:original.description };
      }
      return c;
    });
    if (!cases.length) return initialDb();
    // Only extend an untouched legacy two-case library; never alter user-created/edited cases.
    const originalIds = new Set(['published-lakshmi-2022','published-vikas-2023']);
    if (cases.length === 2 && cases.every(c => c.published && originalIds.has(c.id))) {
      cases = [...cases, ...cloneSeeds().filter(c => !originalIds.has(c.id))];
    }
    if (new Set(cases.map(x => x.id)).size !== cases.length) throw new Error('Duplicate case IDs');
    return { cases, currentId: cases.some(x => x.id === data.currentId) ? data.currentId : cases[0].id };
  } catch {
    storageLocked = true;
    storageWarning = 'Existing browser storage could not be read. It has not been overwritten; back it up before clearing it.';
    return initialDb();
  }
}
const state = { db:loadDb(), view:'overview', filter:'all', caseSearch:'', searchOpen:false, caseSort:'original', navHistory:[], status:{phase:'loading',execution:null}, aiText:'', aiSource:'', aiSourceType:'published', aiUrl:'', aiResult:null, aiBusy:false, reportText:null, reportReviewed:false, pendingDays:null };
function current() { return state.db.cases.find(x => x.id === state.db.currentId) || state.db.cases[0]; }
function save() {
  if (storageLocked) { toast('Previous browser storage is protected. Back it up before clearing it.'); return false; }
  try { localStorage.setItem(STORE, JSON.stringify(state.db)); storageWarning = ''; return true; }
  catch { storageWarning = 'Unable to save in this browser. Export a copy and check your storage settings.'; toast(storageWarning); return false; }
}
function resetTransient() {
  const item=current();
  state.aiText=item?.published ? item.entries[0]?.quote || '' : '';
  state.aiSource=item?.published ? item.entries[0]?.source || '' : '';
  state.aiSourceType=item?.published ? 'published' : 'worker';
  state.aiUrl=item?.published ? item.entries[0]?.url || '' : '';
  state.aiResult=null;state.reportText=null;state.reportReviewed=false;state.pendingDays=null;
}
resetTransient();
let toastTimer;
function toast(message) { toastEl.textContent=message;toastEl.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastEl.classList.remove('show'),4200); }
function actionButton(action,label,style='secondary',ico='',more='') { return `<button class="btn ${style}" type="button" data-action="${h(action)}" ${more}>${ico?icon(ico):''}<span>${h(label)}</span></button>`; }
const nav=[['overview','Workspace','grid'],['records','Evidence','layers'],['assistant','QVAC assistant','spark'],['report','Review draft','file'],['method','About & privacy','info']];
function sidebar() {
  return `<aside class="sidebar"><a class="brand" href="/" aria-label="Athar Attendance home" title="Athar Attendance"><span class="brand-mark"><svg viewBox="0 0 40 40" aria-hidden="true"><path fill="currentColor" d="M20 3.6a16.4 16.4 0 1 0 16.4 16.5h-8.4A8.1 8.1 0 1 1 20 12V3.6Z"/><path fill="#ffb75c" d="M21.4 3.7a16.3 16.3 0 0 1 14.8 13.9h-8.5a8.2 8.2 0 0 0-6.3-5.5V3.7Z"/></svg></span><span class="brand-name">Athar</span></a><button class="rail-back" type="button" data-action="back" title="Back" aria-label="Back" ${state.navHistory.length?'':'disabled'}>${icon('back')}</button><nav class="navigation" aria-label="Main navigation">${nav.map(([key,label,ico])=>`<button class="nav-link ${state.view===key?'active':''}" type="button" data-action="nav" data-view="${key}" title="${h(label)}" aria-label="${h(label)}" ${state.view===key?'aria-current="page"':''}>${icon(ico)}<span>${h(label)}</span></button>`).join('')}</nav><div class="side-bottom"><button class="nav-link quiet" type="button" data-action="nav" data-view="method" title="Privacy and data" aria-label="Privacy and data">${icon('shield')}<span>Privacy</span></button><div class="side-version">v 0.2</div></div></aside>`;
}
function statusLabel(){const phase=state.status.phase;return phase==='ready'?'QVAC ready':phase==='error'?'Model unavailable':'Loading model';}
function statusMarkup(){const s=state.status.phase;return `<span class="status-dot ${s==='ready'?'ready':s==='error'?'error':''}"></span><span>${h(statusLabel())}</span>`;}
const PORTRAITS = { 'published-lakshmi-2022':1, 'published-vikas-2023':2, 'published-anita-2023':5, 'published-kesar-2023':6 };
